CREATE TABLE IF NOT EXISTS `#__decaroresources_resources` (`id` int unsigned NOT NULL AUTO_INCREMENT,`uuid` char(36) NOT NULL,`name` varchar(255) NOT NULL,`resource_type` varchar(50) NOT NULL DEFAULT 'resource',`capacity` int unsigned DEFAULT NULL,`location` varchar(255) DEFAULT NULL,`state` tinyint NOT NULL DEFAULT 1,`access` int unsigned NOT NULL DEFAULT 1,`created` datetime NOT NULL,`created_by` int unsigned NOT NULL DEFAULT 0,`modified` datetime DEFAULT NULL,`modified_by` int unsigned NOT NULL DEFAULT 0,PRIMARY KEY(`id`),UNIQUE KEY `idx_uuid`(`uuid`),KEY `idx_type`(`resource_type`),KEY `idx_state_access`(`state`,`access`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 DEFAULT COLLATE=utf8mb4_unicode_ci;
